const ctx = $('01.2 Build run context').item.json;
const attemptStart = $('01.3 Mark phase1 attempt start').item.json.phase1AttemptStartedAt;
const response = $input.first().json;
const statusCode = response.statusCode;
const body = response.body || {};

if (statusCode !== undefined && statusCode >= 200 && statusCode < 300 && body.phase1ControlReport) {
  return [{
    json: {
      processInstanceId: ctx.processInstanceId,
      correlationId: ctx.correlationId,
      workflowId: $workflow.id,
      receivedAt: ctx.receivedAt,
      outcome: "REPORT",
      report: body.phase1ControlReport,
      httpErrorCode: null,
      n8nErrorCode: null,
      explanation: null,
      phase1AttemptStartedAt: attemptStart,
      gateDecisionAt: null,
      callerOk: true,
      callerStatusCode: statusCode,
      canonicalInvoice: body.canonicalInvoice,
    },
  }];
}

if (statusCode !== undefined) {
  const detail = body.detail && typeof body.detail === "object" ? body.detail : {};
  const httpErrorCode = detail.error_code || "BATCH_ITEM_PROCESSING_FAILED";
  const callerDetail = detail.detail || response.message || "Invoice processing failed.";
  return [{
    json: {
      processInstanceId: ctx.processInstanceId,
      correlationId: ctx.correlationId,
      workflowId: $workflow.id,
      receivedAt: ctx.receivedAt,
      outcome: "HTTP_ERROR",
      report: null,
      httpErrorCode,
      n8nErrorCode: null,
      explanation: callerDetail,
      phase1AttemptStartedAt: attemptStart,
      gateDecisionAt: null,
      callerOk: false,
      callerStatusCode: statusCode,
      callerErrorCode: httpErrorCode,
      callerDetail,
    },
  }];
}

// No statusCode at all: a genuine connection-level failure (03.1's error output).
const errObj = response.error || {};
const errMessage = (errObj.message || errObj || response.message || "").toString();
const errCode = (errObj.code || "").toString();
const isTimeout = /ETIMEDOUT|ECONNABORTED/i.test(errCode) || /timeout/i.test(errMessage);
const outcome = isTimeout ? "TIMEOUT" : "TRANSPORT_FAILURE";
const n8nErrorCode = isTimeout ? "INVOICE_PROCESSING_SERVICE_TIMEOUT" : "INVOICE_PROCESSING_SERVICE_UNAVAILABLE";
const explanation = errMessage || "Invoice processing failed.";

return [{
  json: {
    processInstanceId: ctx.processInstanceId,
    correlationId: ctx.correlationId,
    workflowId: $workflow.id,
    receivedAt: ctx.receivedAt,
    outcome,
    report: null,
    httpErrorCode: null,
    n8nErrorCode,
    explanation,
    phase1AttemptStartedAt: attemptStart,
    gateDecisionAt: null,
    callerOk: false,
    callerStatusCode: 503,
    callerErrorCode: n8nErrorCode,
    callerDetail: explanation,
  },
}];

// No weak fallback: a missing crypto.randomUUID must fail visibly rather
// than mint a low-entropy identity for evidence.
// The n8n JS Task Runner sandbox does not expose a bare `crypto` global
// (confirmed against the real pinned n8nio/n8n:2.33.7 image) -- the built-in
// must be required explicitly, and require() itself is denied unless
// allow-listed (NODE_FUNCTION_ALLOW_BUILTIN=crypto, set on the n8n
// container -- see docker-compose.phase1-upload-demo.yml). No weak
// fallback: an unavailable/disallowed crypto module must fail visibly
// rather than mint a low-entropy identity for evidence.
let randomUUID;
try {
  randomUUID = require("crypto").randomUUID;
} catch (e) {
  randomUUID = undefined;
}
if (typeof randomUUID !== "function") {
  throw new Error(
    "SECURE_UUID_UNAVAILABLE: refusing to mint a weak identifier for correlationId/processInstanceId without crypto.randomUUID() (require(\"crypto\") must be allow-listed via NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance)."
  );
}
const correlationId = randomUUID();
const processInstanceId = randomUUID();

const item = $input.first();
return [{
  json: {
    ...item.json,
    correlationId,
    processInstanceId,
    receivedAt: new Date().toISOString(),
  },
  binary: item.binary,
}];

// Reconciles the shared subworkflow's minimal { activityExecution } return
// with 04.1's own envelope (04.1 is this workflow's sole, unambiguous
// predecessor here -- no branch multiplicity to resolve) to rebuild the
// exact caller-facing batch-item response shape the Batch Demo caller
// already depends on.
const envelope = $('04.1 Build control report').item.json;
const { activityExecution } = $input.first().json;

const responseBody = envelope.outcome === "REPORT"
  ? { ok: true, statusCode: envelope.callerStatusCode, canonicalInvoice: envelope.canonicalInvoice, phase1ControlReport: envelope.report }
  : { ok: false, statusCode: envelope.callerStatusCode, errorCode: envelope.callerErrorCode, detail: envelope.callerDetail };

return [{ json: { ...responseBody, activityExecution } }];
